    private static Set<String> strings(JsonNode values){Set<String> out=new TreeSet<>();for(JsonNode v:values)require(v.isTextual()&&out.add(v.asText()),"DUPLICATE_SOURCE_IDENTITY");return out;}
    private static ArrayNode reasons(ObjectNode row){return (ArrayNode)row.path("reasons");}
