    private static JsonNode rule(JsonNode policy,String code,String key){JsonNode v=policy.path("symbol_overrides").path(code).get(key);return v==null?policy.path("limits").get(key):v;}
    /** Actual-size round trip including minimum brokerage on both legs. */
    public static ObjectNode positionMath(BigDecimal price,BigDecimal support,BigDecimal pressure,long shares,JsonNode costs){
        require(shares>0&&price.signum()>0&&support.signum()>0&&pressure.compareTo(support)>0,"SHORT_REFERENCE_UNVERIFIED");
        BigDecimal q=BigDecimal.valueOf(shares),slip=nonnegative(costs.get("slippage_each_side")),fee=nonnegative(costs.get("brokerage_each_side")),tax=nonnegative(costs.get("sell_tax")),floor=nonnegative(costs.get("minimum_fee_twd"));require(slip.compareTo(O)<0&&tax.compareTo(O)<0,"SHORT_COST_DOMAIN_UNVERIFIED");
        BigDecimal gross=price.multiply(q).multiply(O.add(slip)),buy=gross.add(gross.multiply(fee).max(floor)),loss=buy.subtract(sale(support,q,slip,fee,tax,floor)),gain=sale(pressure,q,slip,fee,tax,floor).subtract(buy);ObjectNode out=F.objectNode();put(out,"buy",buy);put(out,"loss",loss);put(out,"gain",gain);put(out,"friction",buy.subtract(price.multiply(q)));return out;
    }
    private static BigDecimal sale(BigDecimal p,BigDecimal q,BigDecimal slip,BigDecimal fee,BigDecimal tax,BigDecimal floor){BigDecimal gross=p.multiply(q).multiply(O.subtract(slip));return gross.subtract(gross.multiply(fee).max(floor)).subtract(gross.multiply(tax));}
