        require("DATE_RANGE".equals(tx.path("selection").path("mode").asText())&&activation.equals(tx.path("selection").path("start").asText())&&today.equals(tx.path("selection").path("end").asText())&&tx.path("records").isArray()&&tx.path("summary").isObject()&&tx.path("allTimeSummary").isObject()&&tx.path("yearSummaries").isArray(),"SHORT_TERM_TRANSACTION_WINDOW_UNVERIFIED");
        List<String> completed=sessions(bundle,activation,today);Set<String> validSessions=new HashSet<>(completed);validSessions.add(today);Set<String> universe=strings(policy.path("symbols"));Map<String,JsonNode> assignments=new HashMap<>(),definitions=new LinkedHashMap<>();
